const staticData = $getWorkflowStaticData('global');
const semrush = $('Fetch SEMrush Rankings').first()?.json || {};
const ga4 = $('Fetch GA4 Traffic').first()?.json || {};
const competitorHtml = $('Scrape Competitor Pages').first()?.json?.data || '';
const competitorHash = require('crypto').createHash('md5').update(String(competitorHtml)).digest('hex');
const previousHash = staticData.lastCompetitorHash;
const competitorChanged = previousHash ? previousHash !== competitorHash : false;
staticData.lastCompetitorHash = competitorHash;
return [{ json: { semrush, ga4, competitorChanged } }];
